        var body = D.createElement('p'); body.className = 'r5-terms__body';
        body.innerHTML = g.items.map(function (x) { return x.replace(/[,.;]\s*$/, ''); }).join(g.items.length > 1 ? ', ' : '');
        if (g.items.length > 1) body.innerHTML = body.innerHTML.charAt(0).toUpperCase() + body.innerHTML.slice(1);
        c.appendChild(body); grid.appendChild(c);
