    var titles = D.querySelectorAll('.t-rec[data-record-type="1052"] .t1052__title');
    for (var i = 0; i < titles.length; i++) {
      var t = titles[i]; if (t.__r5) continue;
      var mm = t.innerHTML.match(/^\s*(\d{1,2})\s*<br\s*\/?>\s*([\s\S]+)$/i);
      if (!mm) continue; t.__r5 = 1;
      t.innerHTML = '<span class="r5-num">' + (+mm[1]) + '</span><span class="r5-head">' + mm[2] + '</span>';
      var rec = t.closest('.t-rec'); if (rec) rec.classList.add('r5-values');
    }
