/* school-decision fixes for steam (lane D-steam-start), DECISIONS.md 2026-10-16. Runtime only: bake into Tilda at handover.
   D1  STEAM consultation block (homes): phone line is STEAM admissions +7 700 055 0051 (tel:+77000550051).
   D2  any wa.me link to the old 7000550051 / 77000550051 number goes to wa.me/77750072332.
   D3  info@harmony.edu.kz is never shown: dropped where admission@ is already in the same list, else becomes admission@.
   D11 /team (RU / KZ / EN): the hero "see the vacancies" CTA is hidden while the page says there are no vacancies.
   D12 "Northwestern Polytechnic University" reads "San Francisco Bay University" (text and img alt / title).
   Orchestrator: "FaceID" reads "Face ID" (RU / KZ homes).
   Every rule is idempotent. */
(function () {
  var D = document, R = D.documentElement;
  if (R.getAttribute('data-site') && R.getAttribute('data-site') !== 'steam') return;
  var path = (location.pathname.replace(/\/+$/, '') || '/');
  var home = /^\/(kz|en)?$/.test(path) || path === '/', team = /^(\/(kz|en))?\/team$/.test(path);

  var TX = [
    [/Northwestern[\s ]+Polytechnic[\s ]+University/g, 'San Francisco Bay University'],
    [/FaceID/g, 'Face ID']
  ];
  function fixNode(n) {
    var p = n.parentNode; if (!p || /^(SCRIPT|STYLE|TEXTAREA|NOSCRIPT)$/.test(p.nodeName)) return;
    var s = n.data, t = s;
    for (var i = 0; i < TX.length; i++) t = t.replace(TX[i][0], TX[i][1]);
    if (t !== s) n.data = t;
  }
  function walk(root) {
    if (!root) return;
    if (root.nodeType === 3) { fixNode(root); return; }
    if (root.nodeType !== 1) return;
    var w = D.createTreeWalker(root, 4), n; while ((n = w.nextNode())) fixNode(n);
  }

  var NO_VAC = /открытых[\s ]+вакансий[\s ]+нет|ашық[\s ]+бос[\s ]+орындар[\s ]+жоқ|no[\s ]+open[\s ]+positions/i;
  function els() {
    var i, l;
    /* D12 attributes */
    l = D.querySelectorAll('img[alt*="Northwestern"], [title*="Northwestern"], [aria-label*="Northwestern"]');
    for (i = 0; i < l.length; i++) ['alt', 'title', 'aria-label'].forEach(function (a) {
      var v = l[i].getAttribute(a); if (v && /Northwestern/.test(v)) l[i].setAttribute(a, v.replace(TX[0][0], 'San Francisco Bay University'));
    });
    /* D2 */
    l = D.querySelectorAll('a[href*="wa.me/"], a[href*="whatsapp"]');
    for (i = 0; i < l.length; i++) {
      var h = l[i].getAttribute('href') || '';
      if (/(wa\.me\/|phone=)7?7000550051/.test(h)) l[i].setAttribute('href', h.replace(/7?7000550051/, '77750072332'));
    }
    /* D1: STEAM consultation block phone line */
    if (home) {
      l = D.querySelectorAll('.k-consult__lines > a.k-consult__line[href^="tel:+77750072332"]');
      for (i = 0; i < l.length; i++) {
        l[i].setAttribute('href', 'tel:+77000550051');
        l[i].textContent = l[i].textContent.replace(/\+7[\s ]*775[\s ]*007[\s ]*23[\s ]*32/, '+7 700 055 0051');
      }
    }
    /* D3 */
    l = D.querySelectorAll('a[href^="mailto:info@harmony.edu.kz"]');
    for (i = 0; i < l.length; i++) {
      var a = l[i], box = a.parentNode && (a.parentNode.closest('.k-consult__lines, ul, ol') || a.parentNode);
      if (box && box.querySelector('a[href^="mailto:admission@harmony.edu.kz"]')) {
        var li = a.parentNode.nodeName === 'LI' ? a.parentNode : a; li.parentNode.removeChild(li); continue;
      }
      a.setAttribute('href', 'mailto:admission@harmony.edu.kz');
      var w = D.createTreeWalker(a, 4), n;
      while ((n = w.nextNode())) if (/info@harmony\.edu\.kz/.test(n.data)) n.data = n.data.replace(/info@harmony\.edu\.kz/, 'admission@harmony.edu.kz');
    }
    /* D11 */
    if (team && D.body && NO_VAC.test(D.body.textContent)) {
      l = D.querySelectorAll('.t-hero__button a[href="#vacancies"]');
      for (i = 0; i < l.length; i++) { var b = l[i].closest('.t-hero__button'); if (b && !b.hasAttribute('data-dec-hide')) b.setAttribute('data-dec-hide', ''); }
    }
  }

  function all() { walk(D.body); els(); }
  var mo = null;
  function ready() {
    all();
    mo = new MutationObserver(function (ms) {
      for (var i = 0; i < ms.length; i++) {
        var m = ms[i];
        if (m.type === 'characterData') fixNode(m.target);
        else for (var j = 0; j < m.addedNodes.length; j++) walk(m.addedNodes[j]);
      }
      els();
    });
    mo.observe(D.body, { childList: true, subtree: true, characterData: true });
  }
  if (D.readyState === 'loading') D.addEventListener('DOMContentLoaded', ready); else ready();
  addEventListener('load', function () { all(); setTimeout(function () { all(); if (mo) mo.disconnect(); }, 9000); });
})();

/* nav-steam.js (lane N-steam, 2026-10-16). The school's 7-item menu and the new pages /about, /program, /wellbeing
   (RU / KZ / EN), which Tilda made by duplicating the homepages (markup/inner/copies.json; the runtime treats them as
   homepages with re-keyed record ids). Runs in <head>, last of the STEAM kit scripts.
   1. Menu state: the item for this page (header nav, phone/tablet menu, header «Контакты» button, footer column) gets
      aria-current="page" as the header and footer are inserted (before paint). The two header disclosures (menu,
      language) close on Escape, on a click outside and when the other one opens.
   2. New pages only (html[data-hs-copy="about|program|wellbeing"]):
      - H1: About and Program lost the hero H1 with the hero; their first section heading becomes the H1 (same classes,
        same look). Wellbeing's heading is already an H1 in Tilda.
      - the homepage-only runtime fixes of fix-steam.js / dec-steam.js / v9.js, which key on the homepage path or on the
        hero: consent line under the form, STEAM admissions phone in the consultation block, EN double space, the campus
        photo caption and the facts row moved into the story record (About).
      - Wellbeing: the text block's six items become a grid of left-aligned items (.nv-wb, nav-steam.css).
   Runtime only: bake into Tilda / markup at handover. Every step is idempotent. */
(function () {
  var D = document, R = D.documentElement;
  if (R.getAttribute('data-site') && R.getAttribute('data-site') !== 'steam') return;
  var path = location.pathname.replace(/\/+$/, '') || '/';
  var m = path.match(/^(?:\/(kz|en))?\/(about|program|wellbeing)$/);
  var lg = (path.match(/^\/(kz|en)(\/|$)/) || [])[1] || 'ru';
  var copy = m ? m[2] : null;
  if (copy) R.setAttribute('data-hs-copy', copy);
  var isHome = /^\/((kz|en))?$/.test(path) || path === '/';

  /* 1. current item */
  function here(a) {
    var h = a.getAttribute('href'); if (!h || h.charAt(0) === '#') return false;
    try { var u = new URL(h, location.href); } catch (e) { return false; }
    return u.host === location.host && (u.pathname.replace(/\/+$/, '') || '/') === path && !u.hash;
  }
  function mark() {
    if (isHome) return;
    var l = D.querySelectorAll('.hdr__nav a, .nav-d__menu a, .hdr__cta, .foot__col a');
    for (var i = 0; i < l.length; i++) {
      var on = here(l[i]);
      if (on && l[i].getAttribute('aria-current') !== 'page') l[i].setAttribute('aria-current', 'page');
      else if (!on && l[i].getAttribute('aria-current') === 'page') l[i].removeAttribute('aria-current');
    }
  }
  function closeAll(except) {
    var l = D.querySelectorAll('.hdr details[open]');
    for (var i = 0; i < l.length; i++) if (l[i] !== except) l[i].removeAttribute('open');
  }
  D.addEventListener('toggle', function (e) { var t = e.target; if (t.matches && t.matches('.hdr details') && t.open) closeAll(t); }, true);
  D.addEventListener('click', function (e) {
    var t = e.target; if (!t.closest) return;
    if (!t.closest('.hdr details')) closeAll(null);
    else if (t.closest('.nav-d__menu a, .lang-d__menu a')) closeAll(null);
  });
  D.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var o = D.querySelector('.hdr details[open]'); if (!o) return;
    o.removeAttribute('open'); var s = o.querySelector('summary'); if (s) s.focus();
  });

  /* 2. new pages */
  var CONSENT = { ru: 'Нажимая кнопку, вы соглашаетесь с обработкой персональных данных.',
    kz: 'Батырманы басу арқылы жеке деректерді өңдеуге келісесіз.',
    en: 'By clicking the button, you agree to personal data processing.' };
  var CAP = { ru: 'Кампус Harmony STEAM, Астана', kz: 'Harmony STEAM кампусы, Астана', en: 'Harmony STEAM campus, Astana' };

  function h1() {
    if (copy === 'wellbeing' || D.querySelector('#allrecords h1')) return;
    var h = copy === 'program' ? D.querySelector('#allrecords .hs > section.stages .stages__title')
      : D.querySelector('#allrecords .t-rec:not([data-record-type="131"]) h2.t-section__title');
    if (!h || h.nodeName === 'H1') return;
    var n = D.createElement('h1');
    for (var i = 0; i < h.attributes.length; i++) n.setAttribute(h.attributes[i].name, h.attributes[i].value);
    while (h.firstChild) n.appendChild(h.firstChild);
    h.parentNode.replaceChild(n, h);
  }
  function consent() {
    var rec = D.querySelector('#allrecords .t-rec[data-record-type="678"]'), form = rec && rec.querySelector('form');
    if (!form || rec.querySelector('.t678__form-bottom-text')) return;
    var col = form.closest('.t-col') || form.parentNode, box = form;
    while (box.parentNode && box.parentNode !== col) box = box.parentNode;
    var d = D.createElement('div'); d.className = 't678__form-bottom-text t-text t-text_xs'; d.setAttribute('field', 'text');
    d.setAttribute('data-hs-fix', ''); d.textContent = CONSENT[lg];
    col.insertBefore(d, box.nextSibling);
  }
  function phone() {   /* D1, as dec-steam.js does on the homepages */
    var l = D.querySelectorAll('.k-consult__lines > a.k-consult__line[href^="tel:+77750072332"]');
    for (var i = 0; i < l.length; i++) {
      l[i].setAttribute('href', 'tel:+77000550051');
      l[i].textContent = l[i].textContent.replace(/\+7[\s ]*775[\s ]*007[\s ]*23[\s ]*32/, '+7 700 055 0051');
    }
  }
  function text() {   /* fix-steam.js /en rule on the copied team record */
    if (lg !== 'en' || !D.body) return;
    var w = D.createTreeWalker(D.body, 4), n;
    while ((n = w.nextNode())) if (/school management\.[\s ]{2,}Coordinator/.test(n.data)) n.data = n.data.replace(/school management\.[\s ]{2,}Coordinator/, 'school management. Coordinator');
  }
  function story() {   /* v9.js story(), which waits for the homepage hero */
    if (copy !== 'about') return;
    var img = D.querySelector('#allrecords .t480 .t480__blockimg'); if (!img) return;
    var rec = img.closest('.t-rec');
    if (!rec.querySelector('.v9-caption')) {
      var cap = D.createElement('p'); cap.className = 'v9-caption'; cap.textContent = CAP[lg];
      img.parentNode.insertBefore(cap, img.nextSibling);
    }
    var nx = rec.nextElementSibling;
    while (nx && nx.offsetParent === null && !nx.querySelector('.t1052')) nx = nx.nextElementSibling;
    var facts = nx && nx.querySelector(':scope > .t1052.k-stat');
    if (facts && !facts.querySelector('.t-section__title')) {
      var col = rec.querySelector('.t480__col:not(.t480__top)');
      if (col) { col.parentNode.insertBefore(facts, col); nx.classList.add('v9-gone'); facts.classList.add('v9-facts'); }
    }
  }
  function wellbeing() {
    if (copy !== 'wellbeing') return;
    var t = D.querySelector('#allrecords .t1152 .t-container:not(.js-block-header) [field="text"]');
    if (!t || t.querySelector('.nv-wb')) return;
    var parts = t.innerHTML.split(/<br\s*\/?>\s*<br\s*\/?>/i);
    if (parts.length < 2) return;
    var ul = D.createElement('ul'); ul.className = 'nv-wb';
    for (var i = 0; i < parts.length; i++) {
      var li = D.createElement('li'); li.className = 'nv-wb__item';
      li.innerHTML = parts[i].replace(/^\s*(<strong>[\s\S]*?<\/strong>)\s*<br\s*\/?>/i, '<p class="nv-wb__head">$1</p><p class="nv-wb__text">') + '</p>';
      ul.appendChild(li);
    }
    t.innerHTML = ''; t.appendChild(ul); t.closest('.t-rec').classList.add('nv-wb-rec');
  }
  function copies() { if (!copy) return; h1(); consent(); phone(); text(); wellbeing(); }

  var mo = new MutationObserver(function () { mark(); });
  mo.observe(R, { childList: true, subtree: true });
  function ready() { mark(); copies(); story(); }
  if (D.readyState === 'loading') D.addEventListener('DOMContentLoaded', ready); else ready();
  addEventListener('load', function () { ready(); setTimeout(function () { ready(); mo.disconnect(); }, 4500); });
})();
